#include <bits/stdc++.h>
using namespace std;
enum Color {
    RED, BLACK
};
struct Node {
    int key;
    Color c=RED;
    Node*l=nullptr, *r=nullptr;
    Node(int k):key(k) {}
};
Node* rotL(Node*h) {
    Node*x=h->r;
    h->r=x->l;
    x->l=h;
    x->c=h->c;
    h->c=RED;
    return x;
}
Node* rotR(Node*h) {
    Node*x=h->l;
    h->l=x->r;
    x->r=h;
    x->c=h->c;
    h->c=RED;
    return x;
}
void flip(Node*h) {
    h->c=RED;
    if (h->l)h->l->c=BLACK;
    if (h->r)h->r->c=BLACK;
}
bool isRed(Node*n) {
    return n&&n->c==RED;
}
Node* ins(Node*h, int k) {
    if (!h)return new Node(k);
    if (k<h->key)h->l=ins(h->l, k);
    else if (k>h->key)h->r=ins(h->r, k);
    if (isRed(h->r)&&!isRed(h->l))h=rotL(h);
    if (isRed(h->l)&&isRed(h->l->l))h=rotR(h);
    if (isRed(h->l)&&isRed(h->r))flip(h);
    return h;
}
